INSERT INTO "doctors_doctor" ("id", "created_at", "updated_at", "is_deleted", "full_name", "email", "phone", "experience_years", "qualification", "bio", "avatar_url", "is_active", "created_by_id", "updated_by_id", "user_id", "certificate_url", "verification_status") VALUES ('66beb46c-0cf7-4e70-991c-6824d86e9af0', '2026-09-05 15:35:02.200401+00:00', '2026-09-11 11:39:42.672786+00:00', False, 'Md. Aminul Islam Joarder', 'joarder@gmail.com', '+8801722334455', 22, 'MBBS, MS (Surgery), FACS', 'Dr. Md. Aminul Islam Joarder is a senior Gastroenterology and General Surgery specialist with 22 years of clinical experience. He completed MBBS from SSMC Dhaka, MS (Surgery) from BSMMU, and is a Fellow of the American College of Surgeons (FACS). He specializes in upper GI endoscopy, laparoscopic cholecystectomy, and complex abdominal surgeries.', 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=400&auto=format&fit=crop&q=80', True, NULL, NULL, 'be44fab3-fe32-48d0-be92-080f62c77312', 'https://www.doctorbangladesh.com/#google_vignette', 'VERIFIED') ON CONFLICT DO NOTHING;
